      "id": "p-056",
      "sectionId": "act-1",
      "fr": "ANTOINE (posant sa main sur celle de Geneviève pour la retenir) : Prends garde, Geneviève... La vérité que tu réclames avec tant de fureur pourrait être plus écrasante que le doute lui-même. (La découverte des dossiers de dénonciation — réplique 56)",
