      "id": "p-812",
      "sectionId": "act-3",
      "fr": "CLÉMENT (entrant sans armes, la voix assourdie par le recueillement) : J'ai démissionné de la commission d'épuration, Antoine. Ta parole m'a fait comprendre que nous risquions de devenir les sosies spirituels de nos anciens oppresseurs. (Le retour du tribunal et la grâce présidentielle — réplique 812)",
